private oldest: Iterator<K> = this.map.keys(); // ONE long-lived iterator

private evictOldest(reason: EvictionReason): void {
  let next = this.oldest.next();
  if (next.done) {
    this.oldest = this.map.keys();
    next = this.oldest.next();
    if (next.done) return;
  }
  const key = next.value;
  const entry = this.map.get(key)!;
  this.evict(key, this.now() >= entry.deadAt ? "expired" : reason);
}
// the slow version was, per eviction:  const key = this.map.keys().next().value;

// real, src/cache.ts (trimmed): the hit path
get(key: K): V | undefined {
  const entry = this.fresh(key);          // live(): map.get + now() vs deadAt; then now() vs expiresAt
  if (entry === undefined) { this.counters.misses++; return undefined; }
  this.hit(key, entry);                   // counters + touch()
  return entry.value;
}
private touch(key: K, entry: Entry<V>): void {
  this.map.delete(key);                   // move to the most-recent end
  this.map.set(key, entry);
}

