private leave(key: K, flight: Flight<V>, reason: unknown): void {
  flight.waiters--;
  if (flight.waiters > 0 || flight.settled) return;
  if (this.flights.get(key) === flight) this.flights.delete(key);
  flight.controller.abort(reason);
  emit(this.options.onEvent, { type: "load-abort", key });
}
// real, src/adapters/http.ts
export function requestSignal(res: ServerResponse): AbortSignal {
  const controller = new AbortController();
  res.once("close", () => {
    if (!res.writableFinished) controller.abort(new Error("client closed the connection"));
  });
  return controller.signal;
}

