import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { isNotFound, loadForRequest, NOT_FOUND_BODY, requestSignal, type CachedResponseOptions, type Loadable } from "./http.js";

export interface HttpCacheOptions<V> extends CachedResponseOptions<V> {
  cacheControl?: string; // e.g. "private, max-age=30" -- never "public" for per-user data
  etag?: boolean;
}

export function cachedJsonHttp<V, Req extends IncomingMessage = IncomingMessage>(
  cache: Loadable<V>, options: HttpCacheOptions<V>, produce: (req: Req, signal: AbortSignal) => Promise<V> | V,
) {
  const notFound = options.notFound ?? isNotFound;
  return function (req: Req, res: ServerResponse, next: (e?: unknown) => void): void {
    const signal = requestSignal(res);
    loadForRequest(cache, options, req, signal, (s) => produce(req, s))
      .then(({ value, status }) => {
        if (res.writableEnded || res.destroyed) return;
        res.setHeader("x-cache", status);
        if (notFound(value)) {
          res.statusCode = 404;
          res.setHeader("content-type", "application/json; charset=utf-8");
          res.end(JSON.stringify(NOT_FOUND_BODY));
          return;
        }
        const body = JSON.stringify(value);
        if (options.cacheControl) res.setHeader("cache-control", options.cacheControl);
        if (options.etag) {
          const tag = `"${createHash("sha1").update(body).digest("base64url").slice(0, 27)}"`;
          res.setHeader("etag", tag);
          if (req.headers["if-none-match"] === tag) {
            res.statusCode = 304;
            res.end();
            return;
          }
        }
        res.statusCode = 200;
        res.setHeader("content-type", "application/json; charset=utf-8");
        res.end(body);
      })
      .catch((error: unknown) => {
        if (signal.aborted) return;
        next(error);
      });
  };
}

