it("ETag: a matching If-None-Match gets 304 and the producer still ran once", async () => {
  let calls = 0;
  const cache = new LruCache<string, { n: number }>({ maxEntries: 10 });
  const app = express();
  app.get("/e", cachedJsonHttp(cache, { key: () => "e", etag: true, cacheControl: "private, max-age=30" }, () => ({ n: ++calls })));
  const base = await listen(app);
  const a = await fetch(`${base}/e`);
  const tag = a.headers.get("etag")!;
  expect([a.status, a.headers.get("cache-control"), await a.json()]).toEqual([200, "private, max-age=30", { n: 1 }]);
  const b = await fetch(`${base}/e`, { headers: { "if-none-match": tag } });
  expect([b.status, b.headers.get("x-cache"), calls]).toEqual([304, "hit", 1]);
});

