import type { Context } from "koa";
import { isNotFound, loadForRequest, NOT_FOUND_BODY, requestSignal, type CachedResponseOptions, type Loadable } from "./http.js";

export function cachedJsonKoa<V>(
  cache: Loadable<V>, options: CachedResponseOptions<V>, produce: (ctx: Context, signal: AbortSignal) => Promise<V> | V,
) {
  const notFound = options.notFound ?? isNotFound;
  return async function cachedJsonKoaMiddleware(ctx: Context): Promise<void> {
    const signal = requestSignal(ctx.res);
    let result: Awaited<ReturnType<typeof loadForRequest<V>>>;
    try {
      result = await loadForRequest(cache, options, ctx.req, signal, (s) => produce(ctx, s));
    } catch (error) {
      if (signal.aborted) return; // client gone: nothing to answer
      throw error;                // Koa's error handling takes it (not cached)
    }
    const missing = notFound(result.value);
    ctx.set("x-cache", result.status);
    ctx.status = missing ? 404 : 200;
    ctx.type = "application/json";
    ctx.body = JSON.stringify(missing ? NOT_FOUND_BODY : result.value); // a string value stays JSON
  };
}

